function read(){try{const saved=JSON.parse(localStorage.getItem('velvet-room-v1'));if(!saved)return fresh();if(!Number.isFinite(saved.points)||saved.points<0||!Array.isArray(saved.history)||!Array.isArray(saved.friends)||!saved.rooms||typeof saved.rooms!=='object')throw Error();return {...fresh(),...migrateProgress(saved),social:normaliseSocial(saved.social)};}catch{storageError=true;return fresh();}}
