function tables(){const html=tableScene(),r=room();if(!r||backendReady&&!practiceOnly)return html;const strip=`<div class="room-strip"><div><strong>${esc(r.code)}</strong> · ${esc(r.name)}<br><small>${r.players.map(p=>`${esc(p.name)} (${p.you?'You':p.ai?'AI':'demo friend'})`).join(' · ')}</small></div><button class="text-btn" data-tab="rooms">Manage room</button></div>`;return html.replace('<div class="table-layout">',strip+'<div class="table-layout">');}
const header=(eyebrow,title,sub,right='')=>`<div class="heading-row"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2><p>${sub}</p></div>${right}</div>`;
function rankPanel(){const tier=rankForMMR(data.mmr);return `<section class="panel rank-panel"><h3>Your MMR rank ${icon('star')}</h3><div class="rank-emblem">♜</div><div class="rank-name">${tier.name}</div><div class="rating-number">${fmt(data.mmr)} MMR · ${data.wins} wins</div><div class="progress" role="progressbar" aria-label="MMR rank progress" aria-valuenow="${Math.round(tier.progress)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${tier.progress}%"></span></div><div class="progress-label"><span>${tier.next?fmt(tier.next.min-data.mmr)+' MMR to '+tier.next.name:'Highest club rank'}</span><span>${tier.next?.min??'MAX'}</span></div></section>`;}
function friendPanel(){if(backendReady){const friends=(liveHub?.friends??[]).filter(f=>f.status==='accepted');return `<section class="panel friends-panel"><h3>Your company <span class="subtle">ONLINE CLUB</span></h3>${friends.slice(0,3).map(f=>`<div class="friend-row">${avatar(f.user.name[0])}<div class="friend-info"><strong>${esc(f.user.name)}</strong><small>${fmt(f.user.mmr)} MMR</small></div></div>`).join('')||'<p>Add a registered username to find your friends.</p>'}<button class="btn ghost" data-tab="club">Open online club</button></section>`;}return `<section class="panel friends-panel"><h3>The usual company <span class="subtle">LOCAL DEMO</span></h3>${data.friends.slice(0,3).map((f,i)=>`<div class="friend-row">${avatar(f.initial,f.color)}<div class="friend-info"><strong>${esc(f.name)}</strong><small>${esc(f.status)}</small></div>${i<2?'<span class="status-dot" aria-label="Simulated online status"></span>':''}<button class="invite-btn" data-challenge="${i}" aria-label="Challenge ${esc(f.name)}">⚔</button></div>`).join('')||'<p class="empty">Your company starts here. Add a username.</p>'}<div class="panel-footer"><button class="text-btn" data-action="friends">${icon('rooms')} Manage friends</button></div><p class="friends-demo">Sample profiles &amp; simulated presence.</p></section>`;}
function tableScene(){const g=displayGame();return `${tableModeTabs()}${header(g.mode==='ranked'?'RANKED PLAY · FIVE GAMES':'UNRANKED LOUNGE · FIVE GAMES',g.mode==='ranked'?'Your next rank starts here.':'Play at your own pace.',g.mode==='ranked'?'Read the table. Make your move. Build your MMR.':'Five different games. Free rounds. No MMR changes.',`<span class="pill">${g.mode==='ranked'?'MMR matches':'No MMR changes'}</span>`)}${g.mode==='ranked'?mmrHero(data):casualIntro()}${g.id==='poker'&&(!backendReady||practiceSeriesOpen)&&(seriesForRound()??activeCompetition())?seriesStrip(seriesForRound()??activeCompetition(),data.social.tournaments[(seriesForRound()??activeCompetition()).tournamentId]):''}${mobileGameTabs()}<div class="table-layout"><div><section class="table-panel"><div class="table-toolbar"><div class="table-title"><span class="suit">${g.suit}</span><div><strong>${g.name}</strong><small>${g.label} · ${g.practice?'Practice · No MMR':g.mode==='unranked'?'Unranked · No MMR':'Ranked · Free entry'}</small></div></div><div class="table-tools"><span class="tag">${g.practice?'PRACTICE':g.mode==='unranked'?'UNRANKED':'RANKED'}</span><button class="text-btn" data-action="help">${icon('help')} How to play</button></div></div><div class="carpet"><button class="table-arrow prev" data-action="prev" aria-label="Previous game">‹</button><div class="seat dealer">${avatar(g.host?g.host[0]:gameIndex===3?opponentLabel()[0]:'V','green')}<div><small>${g.host?esc(g.host):g.id==='mines'?'Minefield':gameIndex===3?esc(opponentLabel()):'The house'}</small><span>${g.role??(g.id==='mines'?'Logic puzzle':competitionOpponent()?.type==='friend'?'Simulated friend':gameIndex===3?'AI opponent':'AI host')}</span></div></div><div class="table-ellipse ${g.id}-table"><div class="felt"><div class="inner-ring"></div>${tableContent()}${round?.phase==='done'&&['blackjack','baccarat','poker'].includes(g.id)?`<div class="result-tag">${esc(round.title)}</div>`:''}</div></div><div class="seat you">${avatar(playerName()[0].toUpperCase())}<div><small>${esc(playerName())}</small><span>${rankName()} · You</span></div></div><button class="table-arrow next" data-action="next" aria-label="Next game">›</button></div><div class="table-status"><span class="status-message" role="status">${round?esc(round.message):esc(g.sub)}</span><span class="round-badge">${round?.phase==='done'?'ROUND COMPLETE':round?.spinning?'SPINNING':round?'YOUR TURN':'TAKE A SEAT'}</span></div>${g.id==='roulette'?renderRouletteLayout(data,round):''}${round?.phase==='done'?roundSummary():''}<div class="controls"><div class="free-label">${round?.phase==='done'?'READY WHEN YOU ARE':'EVERY ROUND IS FREE'}<strong>${round?.phase==='done'?'Another round. A fresh hand.':'Play for the pleasure of it.'}</strong></div><div class="button-group">${controls()}</div></div></section><div class="bottom-grid"><div class="feature"><div class="feature-icon">${icon('leaderboards')}</div><div><h4>See where you stand.</h4><p>Compare MMR with the club.</p></div><button class="text-btn" data-tab="leaderboards">Standings</button></div><div class="feature"><div class="feature-icon">${icon('rooms')}</div><div><h4>Make it a private table.</h4><p>Good company makes a good game.</p></div><button class="text-btn" data-tab="rooms">Open rooms</button></div></div></div><aside class="right-column">${tableMMRPanel(data,g)}${friendPanel()}</aside></div>`;}
function roundSummary(){const s=seriesForRound();return (currentGame().mode==='unranked'?casualResult(round):mmrResult(round))+(s?seriesRecap(s,data.social.tournaments[s.tournamentId]):'');}
function card(c,{back=false,hold=false,index=-1,held=false}={}){if(back)return '<div class="card back" role="img" aria-label="Face-down card"></div>';const red=['♥','♦'].includes(c.s);const html=`<span class="corner">${face(c)}<span>${c.s}</span></span><span class="pip">${c.s}</span><span class="bottom-corner">${face(c)}${c.s}</span>${held?'<span class="hold-label">HELD</span>':''}`;return hold?`<button class="card holdable ${red?'red':''} ${held?'held':''}" data-hold="${index}" aria-label="${face(c)} ${c.s}, ${held?'held':'tap to hold'}" aria-pressed="${held}">${html}</button>`:`<div class="card ${red?'red':''}" role="img" aria-label="${face(c)} ${c.s}">${html}</div>`;}
const cards=cs=>cs.map(c=>card(c)).join('');
function tableContent(){const id=currentGame().id,r=round;if(['connect4','memory','slide','lights','codebreaker'].includes(id))return renderExtra(currentGame(),r);if(id==='mines')return renderMines(r?.board);const brand=`<div class="table-brand">THE VELVET ROOM<small>${id==='blackjack'?'TWENTY-ONE · NO STAKES':id==='poker'?'FIVE CARDS. YOUR CALL.':'A LITTLE MOMENT OF PLAY'}</small></div>`;if(id==='roulette'){const colours=WHEEL_ORDER.map((n,i)=>`${{red:'#932d37',black:'#182921',green:'#226044'}[wheelColour(n)]} ${i*360/37}deg ${(i+1)*360/37}deg`).join(',');return `<div class="wheel-wrap"><div class="wheel" style="background:conic-gradient(from -${180/37}deg,${colours});transform:rotate(${r?.angle??0}deg)">${WHEEL_ORDER.map((n,i)=>`<span class="wheel-num" style="--a:${i*360/37}deg">${n}</span>`).join('')}</div><div class="target-mark" style="--target:0deg"></div><div class="wheel-pointer" style="--angle:0deg"></div>${r?.phase==='done'?`<div class="wheel-result-number ${wheelColour(r.number)}">${r.number}<small>${wheelColour(r.number)}</small></div>`:''}</div><div class="wheel-text">${r?.phase==='done'?'EXHIBITION COMPLETE · NO STAKES':r?.spinning?'FIVE-SECOND AUTOMATIC SPIN':'A MOMENT ON THE HOUSE'}</div>`;}
if(id==='baccarat'){
  const p=r?.player??[{r:14,s:'♠'},{r:7,s:'♥'}];
  const b=r?.banker??[{r:3,s:'♣'},{r:3,s:'♦'}];
  const reveal=r?.phase==='done';
  return `<div class="baccarat-zone left"><span class="zone-label">${reveal?`PLAYER · ${baccaratTotal(p)}`:'PLAYER'}</span><div class="cards">${cards(p)}</div></div>
  <div class="baccarat-zone right"><span class="zone-label">${reveal?`BANKER · ${baccaratTotal(b)}`:'BANKER'}</span><div class="cards">${cards(b)}</div></div>
  <div class="baccarat-center">NINE-POINT CHALLENGE · HAND ${r?.handNumber??1}/5</div>`;
}
const p=r?.player??(id==='poker'?[{r:14,s:'♠'},{r:14,s:'♥'},{r:13,s:'♣'},{r:10,s:'♦'},{r:7,s:'♣'}]:[{r:13,s:'♠'},{r:14,s:'♦'}]);const d=r?.dealer??[{r:10,s:'♣'},{r:8,s:'♦'}];const hidden=!(r?.phase==='done');return `${brand}<div class="dealer-zone"><div class="zone-label">${id==='poker'?esc(opponentLabel())+' · '+(competitionOpponent()?.type==='friend'?'DEMO':'AI'):`DEALER${!hidden?' · '+total(d):''}`}</div><div class="cards">${id==='poker'?(r?.phase==='done'?cards(d):Array.from({length:5},()=>card(null,{back:true})).join('')):d.map((c,i)=>card(c,{back:hidden&&i>0})).join('')}</div></div><div class="player-zone"><div class="cards">${p.map((c,i)=>card(c,{hold:id==='poker'&&r?.phase==='playing',index:i,held:r?.held?.includes(i)})).join('')}</div><div class="zone-label">${id==='poker'?(r?.phase==='done'?pokerRank(p).name:'YOUR HAND'):`YOUR HAND · ${total(p)}`}</div></div>${id==='blackjack'?`<div class="chip-stack" aria-hidden="true"><span class="chip">V</span><span class="chip gold">V</span><span class="chip">V</span></div><div class="deck-stack">${card(null,{back:true})}</div>`:''}`;}
function controls(){
  if(round?.phase==='done'&&round.seriesId)return competitionButtons();

  if(!round||round.phase==='done'){
    return `<button class="btn gold" data-action="start">${icon('cards')} ${currentGame().id==='roulette'?(round?'Spin again':'Start five-second spin'):(currentGame().mode==='unranked'?(round?'Play again':'Start unranked round'):activeCompetition()&&currentGame().id==='poker'?'Deal series hand':currentGame().id==='mines'?(round?'New minefield':'Start ranked puzzle'):round?'Play ranked again':'Start ranked round')}</button>`;
  }

  const id=currentGame().id;

  if(id==='connect4'){
    return `<label class="sr-only" for="connect-column-select">Drop column</label><select class="connect-column-select" id="connect-column-select">${Array.from({length:7},(_,i)=>i).filter(c=>!round.extra.cells[c]).map(c=>`<option value="${c}" ${c===3?'selected':''}>Column ${c+1}</option>`).join('')}</select><button class="btn gold" data-action="connect-drop">Drop disc</button>`;
  }

  if(['connect4','memory','slide','lights','codebreaker'].includes(id)){
    return `<span class="action-hint">${id==='connect4'?'Choose a column above to drop your gold disc.':id==='memory'?'Turn two tiles to find a matching pair.':id==='slide'?'Slide a tile next to the empty space.':id==='lights'?'Toggle the lights until the board is dark.':'Use the symbols and clue history to crack the code.'}</span>`;
  }

  if(id==='mines'){
    return `<button class="btn ${mineFlagMode?'ghost':'gold'}" data-action="mine-reveal-mode" aria-pressed="${!mineFlagMode}">Reveal mode</button><button class="btn ${mineFlagMode?'gold':'ghost'}" data-action="mine-flag-mode" aria-pressed="${mineFlagMode}">⚑ Flag mode</button>`;
  }

  if(id==='blackjack')return '<button class="btn ghost" data-action="stand">Stand <span class="subtle">S</span></button><button class="btn gold" data-action="hit">Hit <span class="subtle">H</span></button>';
  if(id==='poker')return '<button class="btn gold" data-action="draw">Draw &amp; reveal</button>';

  if(id==='baccarat'){
    return `<span class="action-hint">HAND ${round.handNumber??1}/5 · ${round.correct??0} correct · <span data-baccarat-clock>10s</span></span><button class="btn" data-answer="player">Player</button><button class="btn" data-answer="tie">Tie</button><button class="btn gold" data-answer="banker">Banker</button>`;
  }

  return '<button class="btn gold" disabled>Spinning… <span data-spin-countdown>5.0s</span></button>';
}

function startRound(){
  if(backendReady&&!practiceOnly)return serverStart();
  if(round&&round.phase!=='done')return;

  const d=deck(),id=currentGame().id;
  tableMode=currentGame().mode;
  round={phase:'playing',practice:backendReady&&practiceOnly,d,message:'',started:Date.now(),opponentMMR:currentGame().benchmark,ranked:currentGame().mode==='ranked'};

  if(id==='poker'&&activeCompetition()){
    round.seriesId=activeCompetition().id;
    round.handId=crypto.randomUUID();
    round.opponentMMR=activeCompetition().players.find(p=>p.id!==PLAYER_ID).mmr;
  }

  sound();
  if(startExtraGame(id)){shell();return;}

  if(id==='mines'){
    mineFlagMode=false;
    round.board=newMinefield();
    round.puzzle=true;
    round.opponentMMR=MINE_MMR;
    round.message='Clear the 20 safe cells. Your first reveal opens a safe area.';
    shell();
    return;
  }

  if(id==='blackjack'){
    round.player=[d.pop(),d.pop()];
    round.dealer=[d.pop(),d.pop()];
    round.message=`You have ${total(round.player)}. Hit or stand?`;
    if(total(round.player)===21||total(round.dealer)===21){
      finish(blackjackResult(round.player,round.dealer),'A natural 21 ends the round.');
      return;
    }
  }else if(id==='poker'){
    round.player=Array.from({length:5},()=>d.pop());
    round.dealer=Array.from({length:5},()=>d.pop());
    round.held=[];
    round.message=`Tap cards to hold, then draw once. ${opponentLabel()} plays after you.${round.seriesId?' MMR is recorded at series end.':''}`;
  }else if(id==='baccarat'){
    Object.assign(round,baccaratDeal(d));
    round.handNumber=1;
    round.correct=0;
    round.deadline=Date.now()+10000;
    round.message='Hand 1 of 5 · Calculate both totals and choose within 10 seconds.';
  }else{
    const index=Math.floor(secureRandom()*37);
    round.number=WHEEL_ORDER[index];
    round.destination=spinDestination(index);
    round.angle=0;
    round.spinning=true;
    round.startTime=performance.now();
    round.message='The wheel stops automatically in five seconds. Exhibition: +10 club points, 0 MMR.';
    const spinningRound=round;
    spinTimer=setTimeout(()=>{
      if(round===spinningRound&&round.spinning)completeSpin();
    },SPIN_DURATION);
  }

  shell();
}
                      
function finish(outcome,explanation,customTitle){if(!round||round.phase==='done')return;if(round.seriesId){finishCompetition(outcome,explanation);return;}round.spinning=false;cancelAnimationFrame(spinFrame);clearTimeout(spinTimer);const exhibition=currentGame().id==='roulette',settlement=round.practice?{ranked:false,points:0,delta:0}:settlementForGame(currentGame().id,outcome,data.mmr,round.opponentMMR),earned=settlement.points,delta=settlement.delta,ranked=settlement.ranked;round.ranked=ranked;round.phase='done';round.outcome=outcome;round.earned=earned;round.mmrDelta=delta;round.pointsBefore=data.points;round.mmrBefore=data.mmr;round.rankBefore=rankName();round.title=customTitle||(outcome==='win'?'You win.':outcome==='draw'?'An even hand.':currentGame().id==='baccarat'?'Comparison missed.':'The house wins.');round.resultLabel=currentGame().id==='mines'?(outcome==='win'?'Field cleared':'Mine revealed'):exhibition?'Exhibition complete':outcome==='win'?(currentGame().id==='baccarat'?'Correct comparison':'You win'):outcome==='draw'?'Draw':currentGame().id==='baccarat'?'Comparison missed':'House wins';if(!ranked||currentGame().id==='connect4')round.resultLabel=customTitle??'Round complete';round.message=explanation;data.points+=earned;data.mmr+=delta;data.peakMMR=Math.max(data.peakMMR??data.mmr,data.mmr);round.pointsAfter=data.points;round.mmrAfter=data.mmr;round.rankAfter=rankName();if(!round.practice)data.played++;if(outcome==='win'&&ranked)data.wins++;if(!round.practice)data.history.unshift({id:crypto.randomUUID(),game:currentGame().name,result:exhibition?'exhibition':outcome,points:earned,ranked,mmrDelta:delta,mmrBefore:round.mmrBefore,mmrAfter:data.mmr,opponentMMR:round.opponentMMR,date:new Date().toISOString()});data.history=data.history.slice(0,100);save();sound();shell();}
function hit(){if(round?.server)return serverAction('hit',{});if(currentGame().id!=='blackjack'||round?.phase!=='playing')return;round.player.push(round.d.pop());const t=total(round.player);sound();if(t>21)finish('loss',`Your ${t} is over 21.`);else if(t===21)stand();else{round.message=`You have ${t}. Hit or stand?`;shell();}}
function stand(){if(round?.server)return serverAction('stand',{});if(currentGame().id!=='blackjack'||round?.phase!=='playing')return;while(total(round.dealer)<17)round.dealer.push(round.d.pop());finish(blackjackResult(round.player,round.dealer),`You: ${total(round.player)} · Dealer: ${total(round.dealer)}.`);}
function describeHand(hand){const r=pokerRank(hand);return `${r.name} (${r.kickers.map(n=>face({r:n})).join(', ')})`;}
function draw(){if(round?.server)return serverAction('draw',{held:round.held??[]});if(currentGame().id!=='poker'||round?.phase!=='playing')return;round.player=round.player.map((c,i)=>round.held.includes(i)?c:round.d.pop());round.dealer=aiDraw(round.dealer,round.d);const c=comparePoker(round.player,round.dealer);finish(c>0?'win':c===0?'draw':'loss',`You: ${describeHand(round.player)}. ${opponentLabel()}: ${describeHand(round.dealer)}.`);}
function answer(a){
  if(round?.server)return serverAction('answer',{answer:a});
  if(currentGame().id!=='baccarat'||round?.phase!=='playing')return;

  const good=a!=='timeout'&&Date.now()<=round.deadline&&a===round.answer;
  if(good)round.correct++;

  if(round.handNumber<5){
    Object.assign(round,baccaratDeal(round.d));
    round.handNumber++;
    round.deadline=Date.now()+10000;
    round.timeoutSent=false;
    round.message=`${good?'Correct':'Not quite'} · ${round.correct}/5 correct. Hand ${round.handNumber} of 5 · calculate within 10 seconds.`;
    shell();
    return;
  }

  const outcome=round.correct>=3?'win':'loss';
  finish(
    outcome,
    `Challenge complete · ${round.correct}/5 correct. Final hand: Player ${baccaratTotal(round.player)} · Banker ${baccaratTotal(round.banker)}.`,
    outcome==='win'?'Nine-Point Challenge won.':'Nine-Point Challenge missed.'
  );
}
function animateWheel(){cancelAnimationFrame(spinFrame);function frame(t){if(!round?.spinning||tab!=='tables')return;const state=spinState(t-round.startTime,round.destination);round.angle=state.rotation;const wheel=$('.wheel'),countdown=$('[data-spin-countdown]');if(wheel&&!matchMedia('(prefers-reduced-motion: reduce)').matches)wheel.style.transform=`rotate(${round.angle}deg)`;if(countdown)countdown.textContent=state.remaining.toFixed(1)+'s';if(state.done){completeSpin();return;}spinFrame=requestAnimationFrame(frame);}spinFrame=requestAnimationFrame(frame);}
function completeSpin(){if(round?.server)return serverAction('complete');if(!round?.spinning)return;round.angle=round.destination;data.rouletteHistory=[round.number,...data.rouletteHistory].slice(0,10);finish('exhibition',`The wheel stopped on ${round.number} · ${wheelColour(round.number)}. Participation award; MMR stays the same.`,`${round.number} · ${wheelColour(round.number)}`);}
function changeGame(i){if(round?.phase==='playing'){showDialog('Switch tables?',`<p>Your free practice round is in progress. Leaving a server-ranked match records a loss. Local practice and unranked rounds can be left freely.</p><button class="btn gold" data-confirm-game="${i}">Switch to ${esc(games[i].name)}</button>`);return;}setGame(i);}
async function setGame(i){if(!games[i])return;if(round?.server&&round.phase==='playing'){await serverAction('abandon');if(round?.phase==='playing')return;}practiceOnly=false;practiceSeriesOpen=false;clearTimeout(pairFlipTimer);cancelAnimationFrame(spinFrame);clearTimeout(spinTimer);round=null;gameIndex=i;tableMode=games[i].mode;tab='tables';menu=false;shell();}
function navigate(t){if(backendReady&&t==='club')refreshClub();if(backendReady&&t==='leaderboards')refreshStandings();if(tab==='tables'&&round?.spinning){round.spinning=false;round=null;cancelAnimationFrame(spinFrame);clearTimeout(spinTimer);}tab=t;menu=false;shell();window.scrollTo({top:0,behavior:'instant'});}
const today=()=>new Date().toLocaleDateString('en-CA');
function bank(){const claimed=data.lastClaim===today();return `${header('THE CLUB BANK','A little on the house.', 'Points for playing. Good times for everyone.')}<div class="notice">Club points are fictional, have no real-world value, and are never staked or sold. Every table is free to play.</div><div class="stat-cards"><div class="stat-card"><small>Your club points</small><strong>${fmt(data.points)}</strong><p>Earned, never purchased.</p></div><div class="stat-card"><small>Rounds played</small><strong>${data.played}</strong><p>Your time at the tables.</p></div><div class="stat-card"><small>Club MMR</small><strong>${fmt(data.mmr)}</strong><p>Results, not your balance.</p></div></div><div class="page-grid"><div class="section-card"><h3>Recent activity</h3>${activity()}</div><div><div class="section-card"><div class="result-icon">♜</div><h3>Your daily welcome</h3><p>Drop by for 250 free club points. Available once per calendar day on this device.</p><button class="btn gold" data-action="claim" ${claimed?'disabled':''}>${icon('gift')} ${claimed?'Claimed today':'Claim 250 points'}</button><p class="subtle">${claimed?'A fresh welcome awaits tomorrow.':'No streaks. Just a little welcome.'}</p></div>${rankPanel()}</div></div>`;}
function activity(){return `${data.lastClaim?`<div class="history-row"><div>Daily welcome<small>${esc(data.lastClaim)}</small></div><span class="positive">+250 pts</span><span>Gift</span></div>`:''}${data.history.slice(0,12).map(h=>`<div class="history-row"><div>${esc(h.game)}<small>${new Date(h.date).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})} · ${h.result==='win'?'Win':h.result==='draw'?'Draw':h.result==='exhibition'?'Exhibition':'Practice round'}</small></div><span class="positive">+${h.points} pts</span><span class="${h.mmrDelta>=0?'positive':'negative'}">${h.mmrDelta>=0?'+':''}${h.mmrDelta} MMR</span></div>`).join('')||(!data.lastClaim?`<div class="empty">${icon('clock')}Your story starts at the tables.<br>Play a free round to see your history here.</div>`:'')}`;}
const samples=[['Juniper','J','green',1512,47,17],['Theodore','T','blue',1460,43,14],['Scarlett','S','rose',1384,39,12],['Oliver','O','green',1328,31,10],['Elara','E','rose',1280,27,8],['Felix','F','blue',1248,26,7],['Theo','T','blue',1184,22,5]];
function leaderboards(){return `${header('THE RANKED ROOM','Your ladder. Your story.','Track your MMR, learn from each match, and find your next tier.') }${mmrHero(data)}<div class="rank-hub-tabs" aria-label="Ranked hub views">${[['standings','Standings'],['history','Match history'],['ladder','Rank ladder']].map(([id,title])=>`<button class="${rankView===id?'active':''}" data-rank-view="${id}" aria-pressed="${rankView===id}">${title}</button>`).join('')}</div>${rankView==='history'?rankedHistory(data,historyFilter):rankView==='ladder'?rankLadder(data.mmr):standings()}`;}
function standings(){if(backendReady)return onlineStandings(onlineRows,leaderFilter,friendsOnly,standingsLoading);let profiles=samples.map(([name,initial,color,mmr,wins,weekly],i)=>({name,initial,color,mmr,wins,weekly,weekRating:1200+weekly*9+i*2}));for(const f of data.friends)if(!profiles.some(p=>p.name===f.name))profiles.push({name:f.name,initial:f.initial,color:f.color,mmr:1200,wins:0,weekly:0,weekRating:1200});profiles.push({name:'Alex Morgan',initial:'A',color:'',mmr:data.mmr,wins:data.wins,weekly:data.history.filter(h=>Date.now()-new Date(h.date).getTime()<7*864e5&&h.ranked!==false&&h.result==='win').length,weekRating:1200+data.history.filter(h=>Date.now()-new Date(h.date).getTime()<7*864e5).reduce((a,h)=>a+h.mmrDelta,0),self:true});if(friendsOnly)profiles=profiles.filter(p=>p.self||data.friends.some(f=>f.name===p.name));profiles.sort((a,b)=>(leaderFilter==='weekly'?b.weekRating-a.weekRating:b.mmr-a.mmr)||b.wins-a.wins);return `<div class="notice">Local demo standings. Sample players are illustrative; your own results update on this device. Ranks follow MMR. Elo-style changes depend on the match result and opponent MMR, with a maximum 16-point change. All five Unranked games leave MMR and ranked records unchanged.</div><div class="section-card"><div class="leader-header"><div class="segmented" aria-label="Leaderboard period"><button data-filter="weekly" class="${leaderFilter==='weekly'?'active':''}" aria-pressed="${leaderFilter==='weekly'}">This week</button><button data-filter="all" class="${leaderFilter==='all'?'active':''}" aria-pressed="${leaderFilter==='all'}">All time</button></div><button class="btn small ${friendsOnly?'gold':'ghost'}" data-action="friends-filter" aria-pressed="${friendsOnly}">${icon('rooms')} ${friendsOnly?'Friends only':'All players'}</button></div><div class="overflow-table"><table class="leader-table"><thead><tr><th>PLACE</th><th>PLAYER</th><th>MMR</th><th>RANK</th><th>WINS</th></tr></thead><tbody>${profiles.map((p,i)=>`<tr class="${p.self?'self':''}"><td class="place">${String(i+1).padStart(2,'0')}</td><td><div class="person">${avatar(p.initial,p.color)}<div><strong>${esc(p.name)}${p.self?' · You':''}</strong><small>${rankForMMR(leaderFilter==='weekly'?p.weekRating:p.mmr).name} · ${p.self?'You':'Demo'}</small></div></div></td><td>${fmt(leaderFilter==='weekly'?p.weekRating:p.mmr)}</td><td>${rankForMMR(leaderFilter==='weekly'?p.weekRating:p.mmr).name}</td><td>${leaderFilter==='weekly'?p.weekly:p.wins}</td></tr>`).join('')}</tbody></table></div><p class="subtle">Weekly MMR starts at 1,200 and uses results from the past seven days.</p></div>`;}
function room(){return data.currentRoom?data.rooms[data.currentRoom]:null;}
function lobbyRooms(){const r=room();return `${header('BETTER WITH COMPANY','Your own little corner.', 'Set the table. Bring your people. Stay a while.','<span class="pill">PRACTICE ONLY</span>')}<div class="notice">Rooms, friends, invitations, and ready states are simulated on this device. No messages are sent and no online connection is made. Try the shared demo code <strong>VELVET</strong>.</div><div class="page-grid"><div>${r?activeRoom(r):`<div class="section-card"><h3>A table for your company</h3><p>Create a private local room with up to four seats. Invite sample friends or fill the table with AI.</p><form id="create-room"><div class="field"><label for="room-name">Room name</label><input id="room-name" name="name" maxlength="36" placeholder="The late-night lounge" required></div><div class="field"><label for="room-mode">Room type</label><select id="room-mode" name="mode"><option value="lounge">Casual private room</option><option value="tournament">Four-seat Poker tournament</option></select></div><div id="tournament-options" hidden><div class="field"><label for="create-best-of">Tournament format</label><select id="create-best-of" name="bestOf"><option value="3">Best of 3 · First to 2 wins</option><option value="5">Best of 5 · First to 3 wins</option></select></div><p class="subtle">Open seats fill with AI at start. Five-card draw, semifinals and a final.</p></div><div class="form-row"><div class="field"><label for="create-game">Game</label><select id="create-game" name="game">${games.map(g=>`<option value="${g.id}">${g.name}</option>`).join('')}</select></div><div class="field" id="room-point-goal"><label for="create-limit">Session point goal</label><input id="create-limit" name="limit" type="number" min="100" max="10000" step="50" value="500" required></div></div><p class="subtle">A shared goal for the session. Points are never committed or spent.</p><button class="btn gold" type="submit">${icon('rooms')} Create room</button></form></div>`}<div class="section-card"><h3>Have a room code?</h3><p>Join a room saved on this browser, or try VELVET.</p><form id="join-room"><div class="form-row"><div class="field"><label for="join-code">Room code</label><input id="join-code" name="code" maxlength="8" placeholder="e.g. VELVET" style="text-transform:uppercase" required></div><button class="btn gold" type="submit">Join room</button></div><div class="form-error" id="join-error" role="alert"></div></form></div></div><aside><section class="section-card"><h3>Your company</h3>${data.friends.map((f,i)=>`<div class="friend-row">${avatar(f.initial,f.color)}<div class="friend-info"><strong>${esc(f.name)}</strong><small>Simulated friend</small></div><button class="btn small ghost" data-invite="${i}">Invite</button><button class="btn small gold" data-challenge="${i}">Challenge</button></div>`).join('')||'<p class="empty">Add your first friend below.</p>'}<form id="add-friend"><div class="field"><label for="friend-name">Add by username</label><input id="friend-name" name="username" placeholder="A familiar face" maxlength="24" required></div><button class="btn ghost" type="submit">Add demo friend</button><div class="form-error" id="friend-error" role="alert"></div></form></section>${rankPanel()}</aside></div>`;}
function activeRoom(r){return r.mode==='tournament'?tournamentRoom(r,data.social):loungeRoom(r);}
function loungeRoom(r){const players=r.players;const allReady=players.every(p=>p.ready);const gained=data.history.filter(h=>new Date(h.date).getTime()>=r.created).reduce((a,h)=>a+h.points,0);return `<section class="section-card"><div class="eyebrow">YOUR PRIVATE TABLE</div><h3 style="margin-top:10px">${esc(r.name)}</h3><div class="room-code"><div><span class="subtle">ROOM CODE</span><strong style="display:block;margin-top:5px">${esc(r.code)}</strong></div><button class="btn small ghost" data-action="copy-code">Copy code</button></div><div class="form-row"><div class="field"><label for="room-game">Table game</label><select id="room-game">${games.map(g=>`<option value="${g.id}" ${g.id===r.game?'selected':''}>${g.name}</option>`).join('')}</select></div><div class="field"><label for="room-limit">Point goal</label><input id="room-limit" type="number" min="100" max="10000" step="50" value="${r.limit}"></div></div><p class="subtle">Session progress: ${gained} / ${r.limit} points ${gained>=r.limit?'· Goal reached!':''}</p>${players.map((p,i)=>`<div class="room-seat">${avatar(p.name[0],p.ai?'blue':i?'green':'')}<div class="person"><strong>${esc(p.name)} ${p.you?'· You':''}</strong><small>${p.you?'Local player':p.ai?'AI player':'Simulated human friend'}</small></div><span class="${p.ready?'check':'subtle'}">${p.ready?'✓ Ready':'Not ready'}</span>${!p.you?`<button class="text-btn" data-remove-seat="${i}" aria-label="Remove ${esc(p.name)}">${icon('close')}</button>`:''}</div>`).join('')}${players.length<4?`<div class="empty" style="padding:15px">${4-players.length} open ${4-players.length===1?'seat':'seats'} · Invite a friend or add AI.</div>`:''}<div class="button-group" style="justify-content:flex-start;margin-top:20px"><button class="btn ${players[0].ready?'ghost':'gold'}" data-action="ready">${players[0].ready?'Unready':'Ready up'}</button><button class="btn" data-action="add-ai" ${players.length>=4?'disabled':''}>Add AI</button><button class="btn gold" data-action="room-start" ${!allReady?'disabled':''}>Start round</button><button class="text-btn" data-action="leave-room">Leave room</button></div><p class="subtle">The room launches your local table. Only Poker has an AI opponent; other seats are simulated company.</p></section>`;}
function createRoom(name,game,limit,code){const c=code??Array.from(crypto.getRandomValues(new Uint8Array(6)),n=>'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[n%32]).join('');data.rooms[c]={code:c,name,game,limit,created:Date.now(),players:[{name:'Alex Morgan',you:true,ready:false}]};data.currentRoom=c;save();return data.rooms[c];}
