function beginChallenge(index,bestOf){if(!canCreateCompetition())return;const f=data.friends[index];if(!f)return;const s=makeSeries(playerProfile(data.mmr),friendProfile(f),bestOf);data.social.series[s.id]=s;data.social.active={seriesId:s.id};if(dialog.open)dialog.close();save();resumeCompetition();}
function resumeCompetition(){practiceOnly=backendReady;practiceSeriesOpen=backendReady;const s=activeCompetition();if(!s){toast('This competition is complete. View the results or start a new one.');roomsView='play';navigate('rooms');return;}if(round?.phase==='playing'&&round.seriesId!==s.id){toast('Finish the current hand before resuming your series.');navigate('tables');return;}gameIndex=3;tab='tables';menu=false;if(round?.phase==='playing'&&round.seriesId===s.id){shell();return;}round=null;startRound();$('.table-panel')?.scrollIntoView({block:'start',behavior:'instant'});}
function addRoomAI(){const r=room();if(!r||r.players.length>=4||data.social.tournaments[r.tournamentId]?.status==='playing')return;const name=['Felix AI','Iris AI','Milo AI'].find(n=>!r.players.some(p=>p.name===n));r.players.push({name,ai:true,ready:true});save();shell();}
function newTournament(){if(!canCreateCompetition())return;const r=createRoom('The Friends Cup','poker',500);r.mode='tournament';r.bestOf=3;roomsView='play';save();navigate('rooms');toast('Tournament room created. Invite friends or let AI fill the seats.');}
function tournamentInvite(index){if(!data.friends[index])return;let r=room();if(!r||r.mode!=='tournament'||data.social.tournaments[r.tournamentId]?.status==='complete'){if(!canCreateCompetition())return;r=createRoom('The Friends Cup','poker',500);r.mode='tournament';r.bestOf=3;}if(data.social.tournaments[r.tournamentId]?.status==='playing'){toast('This bracket has started. Invite friends before starting the next tournament.');return;}roomsView='play';invite(index);}
function synchroniseTournament(t){const next=advanceTournament(t);for(const s of tournamentSeries(t)){data.social.series[s.id]=s;if(s.status==='complete')recordSeries(data.social,s);}data.social.active=next&&next.players.some(p=>p.id===PLAYER_ID)?{seriesId:next.id,tournamentId:t.id}:null;return next;}
function startRoomCompetition(){const r=room();if(!r)return;if(r.mode!=='tournament'){if(!r.players.every(p=>p.ready))return;practiceOnly=backendReady;practiceSeriesOpen=false;gameIndex=games.findIndex(g=>g.id===r.game);round=null;tab='tables';startRound();toast('Local room round started. Other seats are simulated.');return;}const existing=data.social.tournaments[r.tournamentId];if(existing?.status==='playing'){if(!activeCompetition())synchroniseTournament(existing);resumeCompetition();return;}if(!r.players.every(p=>p.ready)||!canCreateCompetition())return;while(r.players.length<4){const name=['Felix AI','Iris AI','Milo AI'].find(n=>!r.players.some(p=>p.name===n));r.players.push({name,ai:true,ready:true});}const players=r.players.map(p=>p.you?playerProfile(data.mmr):p.ai?{id:'ai:'+crypto.randomUUID(),name:p.name,type:'ai',mmr:1250}:friendProfile({name:p.name}));const t=makeTournament(players,r.bestOf??3,r.code);data.social.tournaments[t.id]=t;r.tournamentId=t.id;synchroniseTournament(t);save();resumeCompetition();toast('Four seats filled. The semifinals are ready.');}
function finishCompetition(outcome,explanation){const s=seriesForRound();if(!s||round.phase==='done')return;const t=s.tournamentId?data.social.tournaments[s.tournamentId]:null,opponent=s.players.find(p=>p.id!==PLAYER_ID),earned=reward(outcome).points;round.pointsBefore=data.points;round.mmrBefore=data.mmr;round.rankBefore=rankName();if(!applyHand(s,outcome,round.handId))return;s.earnedPoints=(s.earnedPoints??0)+earned;if(!backendReady){data.points+=earned;data.played++;}let delta=0;if(s.status==='complete'){const seriesOutcome=s.winnerId===PLAYER_ID?'win':'loss';if(recordSeries(data.social,s)){delta=backendReady?0:mmrChange(data.mmr,opponent.mmr,seriesOutcome);data.mmr+=delta;data.peakMMR=Math.max(data.peakMMR,data.mmr);if(seriesOutcome==='win'&&!backendReady)data.wins++;data.history.unshift({id:s.id,game:'Poker',result:seriesOutcome,points:s.earnedPoints,mmrDelta:delta,mmrBefore:round.mmrBefore,mmrAfter:data.mmr,opponentMMR:opponent.mmr,date:new Date().toISOString(),ranked:!backendReady,seriesLabel:`Best of ${s.bestOf} vs ${opponent.name}`});data.history=data.history.slice(0,100);}if(t)synchroniseTournament(t);else data.social.active=null;}round.phase='done';round.outcome=outcome;round.earned=earned;round.mmrDelta=delta;round.title=outcome==='win'?'You win the hand.':outcome==='draw'?'Draw · replay the hand.':opponent.name+' wins the hand.';round.resultLabel=s.status==='complete'?(s.winnerId===PLAYER_ID?'You win the series':opponent.name+' wins the series'):round.title;round.message=explanation;round.pointsAfter=data.points;round.mmrAfter=data.mmr;round.rankAfter=rankName();round.competition={finished:s.status==='complete',bestOf:s.bestOf};if(backendReady){round.practice=true;round.earned=0;data.history=data.history.filter(h=>h.id!==s.id);}settleWeeks(data.social);save();sound();shell();}
function socialRooms(){const nav=socialTabs(roomsView);if(roomsView==='play'){const html=lobbyRooms().replace(/<div class="notice">.*?<\/div>/,socialNotice);return html.replace('<div class="page-grid">',nav+competitionLaunch(data)+'<div class="page-grid">');}return `${header('THE SOCIAL CLUB','Friendly faces. Lasting rivalries.','Challenge your company, follow the bracket, and play for cosmetic honours.')}${socialNotice}${nav}${roomsView==='weekly'?weeklyCup(data):rivalView(data,rivalPair)}`;}
function socialClick(button){if(button.dataset.socialView){roomsView=button.dataset.socialView;navigate('rooms');return true;}if(button.dataset.challenge!==undefined){challengeFriend(Number(button.dataset.challenge));return true;}if(button.dataset.tournamentInvite!==undefined){tournamentInvite(Number(button.dataset.tournamentInvite));return true;}if(button.dataset.rival!==undefined){rivalPair=[PLAYER_ID,friendProfile(data.friends[Number(button.dataset.rival)]).id];roomsView='rivals';navigate('rooms');$('.rivalry-detail')?.scrollIntoView({block:'start'});return true;}if(button.dataset.equipTitle){const title=button.dataset.equipTitle;if(data.social.awards.some(a=>a.title===title)){data.social.equippedTitle=title;save();if(dialog.open)dialog.close();shell();toast(title+' equipped.');}return true;}switch(button.dataset.action){case'pick-challenge':pickChallenge();return true;case'new-tournament':newTournament();return true;case'competition-resume':resumeCompetition();return true;case'competition-next':if(activeCompetition())resumeCompetition();else showCompetition();return true;case'show-competition':showCompetition();return true;case'clear-title':data.social.equippedTitle='Club member';save();if(dialog.open)dialog.close();shell();return true;}return false;}
function socialChange(target){if(target.id==='room-mode'){const on=target.value==='tournament';$('#tournament-options').hidden=!on;$('#room-point-goal').hidden=on;$('#create-limit').disabled=on;$('#create-game').disabled=on;if(on)$('#create-game').value='poker';return true;}if(target.id==='room-best-of'){room().bestOf=Number(target.value);save();return true;}if(target.id==='rival-0'||target.id==='rival-1'){rivalPair[Number(target.id.at(-1))]=target.value;shell();return true;}return false;}

function arcadeClick(button){
  if(button.dataset.rouletteNumber!==undefined&&currentGame().id==='roulette'){data.rouletteHighlights=toggleNumber(data.rouletteHighlights,Number(button.dataset.rouletteNumber));data.rouletteGroup=null;save();shell();document.querySelector(`[data-roulette-number="${button.dataset.rouletteNumber}"]`)?.focus({preventScroll:true});return true;}
  if(button.dataset.rouletteGroup&&currentGame().id==='roulette'){const group=rouletteGroup(button.dataset.rouletteGroup);if(group){data.rouletteHighlights=[...group.numbers];data.rouletteGroup=group.id;save();shell();document.querySelector(`[data-roulette-group="${group.id}"]`)?.focus({preventScroll:true});}return true;}
  if(button.dataset.mineCell!==undefined&&currentGame().id==='mines'){playMineCell(Number(button.dataset.mineCell),mineFlagMode);return true;}
  if(button.dataset.action==='clear-roulette'){data.rouletteHighlights=[];data.rouletteGroup=null;save();shell();return true;}
  if(button.dataset.action==='mine-reveal-mode'){mineFlagMode=false;shell();return true;}
  if(button.dataset.action==='mine-flag-mode'){mineFlagMode=true;shell();return true;}
  return false;
}
function playMineCell(index,flag=false){if(round?.server)return serverAction(flag?'flag':'reveal',{index});
  if(currentGame().id!=='mines'||round?.phase==='done')return;
  if(!round)startRound();
  if(flag){const changed=toggleFlag(round.board,index);if(!changed&&!round.board.cells[index].revealed)toast('All five flags are placed. Remove a flag before placing another.');shell();document.querySelector(`[data-mine-cell="${index}"]`)?.focus({preventScroll:true});return;}
  if(!revealCell(round.board,index))return;
  sound();const progress=mineProgress(round.board);
  if(round.board.status==='loss')finish('loss',`A mine was revealed. ${progress.revealed} of ${progress.total} safe cells cleared.`,'Mine revealed.');
  else if(round.board.status==='win')finish('win',`All ${progress.total} safe cells cleared in ${round.board.moves} reveals.`,'Field cleared.');
  else{round.message=`${progress.revealed} of ${progress.total} safe cells cleared. Use the numbers to locate the five mines.`;shell();}
  if(round.phase==='playing')document.querySelector('.mine-cell:not(:disabled)')?.focus({preventScroll:true});
}
document.addEventListener('contextmenu',e=>{const cell=e.target.closest('[data-mine-cell]');if(cell&&currentGame().id==='mines'){e.preventDefault();playMineCell(Number(cell.dataset.mineCell),true);}});
document.addEventListener('keydown',e=>{const cell=e.target.closest?.('[data-mine-cell]');if(!cell||currentGame().id!=='mines'||dialog.open)return;if(e.key.toLowerCase()==='f'){e.preventDefault();playMineCell(Number(cell.dataset.mineCell),true);return;}const directions={ArrowLeft:[0,-1],ArrowRight:[0,1],ArrowUp:[-1,0],ArrowDown:[1,0]},direction=directions[e.key];if(!direction)return;e.preventDefault();let row=Math.floor(Number(cell.dataset.mineCell)/5),col=Number(cell.dataset.mineCell)%5;while(true){row+=direction[0];col+=direction[1];if(row<0||row>=5||col<0||col>=5)return;const next=document.querySelector(`[data-mine-cell="${row*5+col}"]`);if(next&&!next.disabled){next.focus();return;}}});

let pairFlipTimer;
function startExtraGame(id){
  const setup={connect4:newConnect4,memory:newMemory,slide:newSlide,lights:newLights,codebreaker:newCodebreaker}[id];
  if(!setup)return false;
  round.extra=setup();round.message=currentGame().sub;return true;
}
function extraClick(button){
  if(button.dataset.tableMode){requestTableMode(button.dataset.tableMode);return true;}
  if(button.dataset.confirmMode){dialog.close();setTableMode(button.dataset.confirmMode);return true;}
  const b=round?.extra;if(!b||round.phase!=='playing')return false;
  if(button.dataset.connectColumn!==undefined||button.dataset.action==='connect-drop'){const column=Number(button.dataset.connectColumn??$('#connect-column-select').value);if(!dropDisc(b,column,1))return true;sound();if(b.status==='playing'){const ai=chooseConnectMove(b.cells);if(ai!==null)dropDisc(b,ai,2);}if(b.winner===1)finish('win','Your gold discs connect four.','Four in a row.');else if(b.winner===2)finish('loss','Iris connected four burgundy discs.','Iris connects four.');else if(b.status==='draw')finish('draw','The board is full with no winning line.','A full-board draw.');else{round.message='Iris has played. Choose a column for your next gold disc.';shell();document.querySelector(`[data-connect-column="${column}"]:not(:disabled)`)?.focus({preventScroll:true});}return true;}
  if(button.dataset.memoryCell!==undefined){const index=Number(button.dataset.memoryCell);if(!flipMemory(b,index))return true;sound();if(b.status==='win'){finish('win',`All eight pairs found in ${b.turns} turns.`,'Every pair found.');return true;}round.message=b.waiting?'Different symbols. Take a moment, then try another pair.':`${b.matched.filter(Boolean).length/2} of 8 pairs found · ${b.turns} turns.`;shell();if(b.waiting){const sameRound=round;pairFlipTimer=setTimeout(()=>{if(round!==sameRound)return;closeMemory(b);if(tab==='tables'){shell();document.querySelector(`[data-memory-cell="${index}"]`)?.focus({preventScroll:true});}},650);}else document.querySelector('.memory-tile:not(:disabled)')?.focus({preventScroll:true});return true;}
  if(button.dataset.slideTile!==undefined){if(!moveSlide(b,Number(button.dataset.slideTile)))return true;sound();if(b.status==='win')finish('win',`The eight tiles are in order after ${b.moves} moves.`,'Puzzle solved.');else{round.message=`${b.moves} moves · Put 1–8 in order, with the space last.`;shell();document.querySelector('.slide-tile:not(:disabled)')?.focus({preventScroll:true});}return true;}
  if(button.dataset.lightCell!==undefined){const index=Number(button.dataset.lightCell);if(!toggleLights(b,index))return true;sound();if(b.status==='win')finish('win',`All sixteen lights are off after ${b.moves} moves.`,'All lights out.');else{round.message=`${b.cells.filter(Boolean).length} lights remain on · ${b.moves} moves.`;shell();document.querySelector(`[data-light-cell="${index}"]`)?.focus({preventScroll:true});}return true;}
  if(button.dataset.codeSlot!==undefined){const slot=Number(button.dataset.codeSlot);if(!Number.isInteger(slot)||slot<0||slot>3)return true;b.active=slot;shell();document.querySelector('[data-code-symbol="0"]')?.focus({preventScroll:true});return true;}
  if(button.dataset.codeSymbol!==undefined){if(editCode(b,b.active,Number(button.dataset.codeSymbol))){sound();shell();document.querySelector('[data-code-symbol="'+button.dataset.codeSymbol+'"]')?.focus({preventScroll:true});}return true;}
  if(button.dataset.action==='code-clear'){b.draft=Array(4).fill(null);b.active=0;shell();document.querySelector('[data-code-slot="0"]')?.focus({preventScroll:true});return true;}
  if(button.dataset.action==='code-submit'){if(!submitCode(b))return true;sound();const clue=b.guesses.at(-1);if(b.status==='win')finish('win','You cracked the four-symbol code in '+b.guesses.length+' '+(b.guesses.length===1?'guess.':'guesses.'),'Code cracked.');else if(b.status==='loss')finish('loss','Eight guesses used. The secret code is revealed above. Try a fresh lock when you are ready.','The lock held.');else{round.message=clue.exact+' exact position · '+clue.misplaced+' correct symbol, wrong position. '+(8-b.guesses.length)+' guesses left.';shell();document.querySelector('[data-code-slot="0"]')?.focus({preventScroll:true});}return true;}

  return false;
}
function modeGameList(mode=tableMode){return games.filter(g=>g.mode===mode);}
function tableModeTabs(){return `<div class="table-mode-tabs" role="group" aria-label="Table sections">${['ranked','unranked'].map(mode=>`<button data-table-mode="${mode}" aria-pressed="${tableMode===mode}" class="${tableMode===mode?'active':''}"><strong>${mode==='ranked'?'Ranked':'Unranked'}</strong><span>5 games · ${mode==='ranked'?'MMR matches':'No MMR changes'}</span></button>`).join('')}</div>`;}
function gameNav(){return `${tableModeTabs()}<nav class="game-nav" aria-label="${tableMode==='ranked'?'Ranked':'Unranked'} games">${modeGameList().map(g=>{const i=games.indexOf(g);return `<button data-game="${i}" class="${gameIndex===i&&tab==='tables'?'active':''}" ${gameIndex===i&&tab==='tables'?'aria-current="true"':''}><span class="suit">${g.suit}</span>${g.name}${gameIndex===i&&tab==='tables'?'<span class="chosen"></span>':''}</button>`;}).join('')}</nav>`;}
function requestTableMode(mode){if(!['ranked','unranked'].includes(mode)||mode===tableMode&&tab==='tables')return;if(round?.phase==='playing'){showDialog('Switch table section?',`<p>Your current free round is in progress. Leaving an unfinished ranked match records a loss. Unranked rounds can be left freely.</p><button class="btn gold" data-confirm-mode="${mode}">Open ${mode==='ranked'?'Ranked':'Unranked'}</button>`);return;}setTableMode(mode);}
function setTableMode(mode){const next=modeGameList(mode)[0];setGame(games.indexOf(next));window.scrollTo({top:0,behavior:'instant'});}
function cycleTable(direction){const list=modeGameList(),position=list.findIndex(g=>g.id===currentGame().id),next=list[(position+direction+list.length)%list.length];changeGame(games.indexOf(next));}
document.addEventListener('keydown',e=>{if(currentGame().id!=='slide'||round?.phase!=='playing'||dialog.open||!e.target.closest?.('[data-slide-tile]'))return;const offsets={ArrowUp:-3,ArrowDown:3,ArrowLeft:-1,ArrowRight:1},offset=offsets[e.key];if(!offset)return;e.preventDefault();const b=round.extra,blank=b.tiles.indexOf(0),next=blank+offset;if(!slideNeighbours(blank).includes(next))return;const tile=b.tiles[next];if(moveSlide(b,tile)){if(b.status==='win')finish('win',`Solved in ${b.moves} moves.`,'Puzzle solved.');else{round.message=`${b.moves} moves · Put 1–8 in order.`;shell();document.querySelector('.slide-tile:not(:disabled)')?.focus({preventScroll:true});}}});

function mobileGameTabs(){return `<div class="game-tabs" aria-label="${tableMode==='ranked'?'Ranked':'Unranked'} game selector">${modeGameList().map(g=>`<button data-game="${games.indexOf(g)}" class="${g.id===currentGame().id?'active':''}">${g.suit} ${g.name}</button>`).join('')}</div>`;}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-action]');if(!b)return;if(extraClick(b))return;if(arcadeClick(b))return;if(socialClick(b))return;if(b.dataset.tab){navigate(b.dataset.tab);return;}if(b.dataset.game!==undefined){changeGame(Number(b.dataset.game));return;}if(b.dataset.confirmGame!==undefined){dialog.close();setGame(Number(b.dataset.confirmGame));return;}if(b.dataset.hold!==undefined&&round?.phase==='playing'){const i=Number(b.dataset.hold);round.held=round.held.includes(i)?round.held.filter(x=>x!==i):[...round.held,i];sound();shell();$(`[data-hold="${i}"]`)?.focus();return;}if(b.dataset.answer){answer(b.dataset.answer);return;}if(b.dataset.invite!==undefined){invite(Number(b.dataset.invite));return;}if(b.dataset.rankView){rankView=b.dataset.rankView;shell();return;}if(b.dataset.filter){leaderFilter=b.dataset.filter;shell();return;}if(b.dataset.removeSeat!==undefined){room().players.splice(Number(b.dataset.removeSeat),1);save();shell();return;}switch(b.dataset.action){case'ranked':if(dialog.open)dialog.close();rankView='standings';navigate('leaderboards');break;case'rank-ladder':if(dialog.open)dialog.close();rankView='ladder';navigate('leaderboards');break;case'rank-history':if(dialog.open)dialog.close();rankView='history';navigate('leaderboards');break;case'mmr-help':mmrHelp();break;case'menu':menu=!menu;shell();if(menu)document.querySelector('.sidebar .nav button')?.focus();else document.querySelector('.topbar .mobile-toggle')?.focus();break;case'mute':data.muted=!data.muted;save();sound();shell();break;case'help':help();break;case'profile':showDialog('Your time at the club.',`<div style="display:flex;gap:15px;align-items:center">${avatar('A')}<div><strong>Alex Morgan</strong><div class="rank-name">${rankName()} · ${fmt(data.mmr)} MMR</div></div></div>${rankPanel()}${cosmeticCollection(data)}<p>Peak ${fmt(data.peakMMR)} MMR · ${data.played} rounds played. Ranks reflect match results, and every table is free to enter.</p><button class="btn gold" data-action="rank-history">Open ranked match history</button><button class="btn gold" data-action="close-dialog">Back to the club</button>`);break;case'friends':roomsView='rivals';navigate('rooms');break;case'close-dialog':dialog.close();break;case'prev':cycleTable(-1);break;case'next':cycleTable(1);break;case'start':startRound();break;case'hit':hit();break;case'stand':stand();break;case'draw':draw();break;case'claim':if(data.lastClaim!==today()){data.points+=250;data.lastClaim=today();save();shell();toast('250 club points, on the house.');}break;case'friends-filter':friendsOnly=!friendsOnly;shell();break;case'add-ai':addRoomAI();break;case'ready':room().players[0].ready=!room().players[0].ready;save();shell();break;case'room-start':startRoomCompetition();break;case'leave-room':data.currentRoom=null;save();shell();toast('You left the room. Its code is saved on this device.');break;case'copy-code':navigator.clipboard?.writeText(room().code).then(()=>toast('Room code copied.'),()=>toast(`Your room code: ${room().code}`))??toast(`Your room code: ${room().code}`);break;}});
document.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);if(e.target.id==='challenge-match'){beginChallenge(Number(f.get('friend')),Number(f.get('bestOf')));return;}if(e.target.id==='create-room'){const name=f.get('name').trim();if(!name)return;const r=createRoom(name,f.get('mode')==='tournament'?'poker':f.get('game'),Number(f.get('limit')??500));r.mode=f.get('mode');r.bestOf=Number(f.get('bestOf'));roomsView='play';save();shell();toast('Your local room is ready.');}else if(e.target.id==='join-room'){const code=f.get('code').trim().toUpperCase();if(code==='VELVET'&&!data.rooms.VELVET){const r=createRoom('The Velvet Lounge','blackjack',500,'VELVET');r.players.push({name:'Oliver',ready:true,ai:false});}if(!data.rooms[code]){$('#join-error').textContent='Room not found on this device. Try VELVET, or create a room.';return;}data.currentRoom=code;save();shell();toast('Welcome to your local room.');}else if(e.target.id==='add-friend'){const name=f.get('username').trim();if(!name||name.length<2){$('#friend-error').textContent='Enter a username with at least 2 characters.';return;}if(data.friends.some(x=>x.name.toLowerCase()===name.toLowerCase())||name.toLowerCase()==='alex morgan'){$('#friend-error').textContent='That username is already in your company.';return;}data.friends.push({name,initial:name[0].toUpperCase(),color:'green',status:'Local demo profile',demo:true});save();shell();toast(`${name} added as a local demo friend.`);}});
document.addEventListener('change',e=>{if(socialChange(e.target))return;if(e.target.id==='history-game'){historyFilter=e.target.value;shell();$('#history-game')?.focus();return;}if(e.target.id==='room-game'){room().game=e.target.value;save();}if(e.target.id==='room-limit'){if(!e.target.checkValidity()){e.target.reportValidity();return;}room().limit=Number(e.target.value);save();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu){menu=false;shell();document.querySelector('.topbar .mobile-toggle')?.focus();return;}if(dialog.open||['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement?.tagName)||tab!=='tables'||e.repeat)return;if(e.key.toLowerCase()==='h'){e.preventDefault();hit();}if(e.key.toLowerCase()==='s'){e.preventDefault();stand();}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&round?.spinning){if(performance.now()-round.startTime>=SPIN_DURATION)completeSpin();else animateWheel();}});
matchMedia('(max-width:760px)').addEventListener('change',()=>{menu=false;shell();});
setInterval(()=>{if(tab!=='tables'||currentGame().id!=='baccarat'||round?.phase!=='playing')return;const seconds=Math.max(0,Math.ceil(((round.deadline??Date.now())-Date.now())/1000)),clock=$('[data-baccarat-clock]');if(clock)clock.textContent=`${seconds}s`;if(seconds===0&&!round.timeoutSent&&!onlineBusy){round.timeoutSent=true;if(round.server)serverAction('answer',{answer:'timeout'});else answer('timeout');}},200);                      
let currentSocialWeek=weekKey();const newAwards=settleWeeks(data.social);save();shell();if(storageError)toast('Saved data could not be read. A fresh local session is ready.');else if(newAwards.length)toast('New cosmetic title: '+newAwards.at(-1).title);setInterval(()=>{const next=weekKey();if(next!==currentSocialWeek){currentSocialWeek=next;const awards=settleWeeks(data.social);save();shell();if(awards.length)toast('Weekly cup reset. New title: '+awards.at(-1).title);}},60000);



function playerName(){return account?.name??'Alex Morgan';}
function connectionStatus(){return `<div class="connection-strip ${backendReady?'connected':''}" role="status"><span>${backendReady?(onlineBusy?'Saving…':account.guest?'Guest progress saved on the server':'Signed in · Progress saved'): 'Connecting to the club…'}</span><button class="text-btn" data-online="account">${backendReady?(account.guest?'Create account / Sign in':esc(account.name)):'Account'}</button></div>`;}
function applyProfile(p){account=p;for(const key of ['mmr','peakMMR','points','wins','played','lastClaim','history'])data[key]=p[key];Object.assign(data,p.preferences);data.social.equippedTitle=p.preferences.title??'Club member';}
function applyPacket(packet){if(packet.profile)applyProfile(packet.profile);if(packet.round){round=packet.round;if(round.game==='baccarat'&&Number.isFinite(round.remainingMs))round.deadline=Date.now()+round.remainingMs;gameIndex=games.findIndex(g=>g.id===round.game);tableMode=currentGame().mode;if(round.spinning){round.startTime=performance.now()-round.elapsed;clearTimeout(spinTimer);const id=round.id;spinTimer=setTimeout(()=>{if(round?.id===id)completeSpin();},Math.max(20,5020-round.elapsed));}if(round.extra?.waiting){clearTimeout(memoryCloseTimer);const id=round.id;memoryCloseTimer=setTimeout(()=>{if(round?.id===id)serverAction('memory-close');},Math.max(50,(round.flipRemaining??650)+40));}}}
async function onlineTask(fn){if(onlineBusy)return;onlineBusy=true;clubError='';shell();try{return await fn();}catch(e){clubError=e.message;toast(e.message);const err=dialog.querySelector('.online-form-error');if(err)err.textContent=e.message;}finally{onlineBusy=false;shell();}}
async function onlineBoot(){try{let result=await api('GET','/session');if(!result.user)result=await api('POST','/auth/guest',{});setSession(result.csrf);try{if(!localStorage.getItem('velvet-room-legacy-backup'))localStorage.setItem('velvet-room-legacy-backup',localStorage.getItem('velvet-room-v1')??'{}');}catch{}applyProfile(result.user);backendReady=true;round=null;clearTimeout(spinTimer);clearTimeout(memoryCloseTimer);if(result.round)applyPacket({round:result.round});shell();refreshStandings();refreshClub();}catch(e){clubError='The backend is unavailable. Please refresh after the server reconnects.';toast(clubError);app.insertAdjacentHTML('afterbegin','<div class="notice" role="alert">Server connection unavailable. This browser can still play local practice.</div>');}}
async function serverStart(){return onlineTask(async()=>{const result=await api('POST','/games',{game:currentGame().id,requestId:crypto.randomUUID()});applyPacket(result);sound();});}
async function serverAction(type,extra={}){if(!round?.server||onlineBusy)return;const id=round.id,input={type,...extra,version:round.version,requestId:crypto.randomUUID()};return onlineTask(async()=>{try{applyPacket(await api('POST','/games/'+id+'/actions',input));sound();}catch(e){try{applyPacket(await api('GET','/games/'+id));}catch{}throw e;}});}
async function refreshStandings(){if(!backendReady)return;const key=leaderFilter+':'+friendsOnly;standingsLoading=true;try{const result=await api('GET','/leaderboard?period='+leaderFilter+'&friends='+(friendsOnly?'1':'0'));if(key===leaderFilter+':'+friendsOnly)onlineRows=result.players;}catch(e){clubError=e.message;}finally{standingsLoading=false;if(tab==='leaderboards')shell();}}
async function refreshClub(){if(!backendReady||onlineBusy)return;try{const code=liveRoom?.code;const [hub,r]=await Promise.all([api('GET','/club'),code?api('GET','/rooms/'+code):Promise.resolve(null)]);const changed=JSON.stringify(liveHub)!==JSON.stringify(hub)||r&&JSON.stringify(liveRoom)!==JSON.stringify(r.room);liveHub=hub;applyProfile(r?.profile??hub.profile);if(r&&liveRoom?.code===code)liveRoom=r.room;if(changed&&tab==='club')shell();}catch(e){clubError=e.message;if(tab==='club')shell();}}
function openAccount(){showDialog('Your club account.',accountContent(account,backendReady?rankPanel():''));}
function selectedHolds(matchId,hand){const h=onlineHeld[matchId];return h?.hand===hand?h.indices:[];}
async function onlineRoomAction(type,extra={}){return onlineTask(async()=>{const result=await api('POST','/rooms/'+liveRoom.code+'/actions',{type,...extra,requestId:crypto.randomUUID()});liveRoom=result.room;applyProfile(result.profile);});}
document.addEventListener('click',e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.dataset.onlineHold!==undefined){e.preventDefault();e.stopImmediatePropagation();const s=liveRoom.matches.find(s=>s.id===b.dataset.match),i=Number(b.dataset.onlineHold),indices=selectedHolds(s.id,s.hand.number);onlineHeld[s.id]={hand:s.hand.number,indices:indices.includes(i)?indices.filter(n=>n!==i):[...indices,i]};shell();return;}
  if(b.dataset.online){e.preventDefault();e.stopImmediatePropagation();const action=b.dataset.online;
    if(action==='account'){openAccount();return;}if(action==='close-room'){liveRoom=null;refreshClub();shell();return;}
    if(!backendReady){toast('The backend is still connecting. Refresh to retry.');return;}
    if(action==='ask-forfeit'){showDialog('Forfeit this series?',`<p>Your opponent will win this series and its MMR result will be recorded.</p><button class="btn gold" data-online="confirm-forfeit" data-match="${b.dataset.match}">Forfeit series</button>`);return;}if(action==='confirm-forfeit'){dialog.close();onlineRoomAction('forfeit',{matchId:b.dataset.match});return;}
    if(['ready','add-ai','start'].includes(action)){onlineRoomAction(action);return;}
    if(['draw','next-hand'].includes(action)){onlineRoomAction(action,{matchId:b.dataset.match,hand:Number(b.dataset.hand),held:selectedHolds(b.dataset.match,Number(b.dataset.hand))});return;}
    onlineTask(async()=>{
      if(action==='logout'){await api('POST','/auth/logout',{});liveHub=null;liveRoom=null;onlineHeld={};dialog.close();await onlineBoot();}
      else if(action==='open-room'||action==='join-invite'){const result=action==='open-room'?await api('GET','/rooms/'+b.dataset.code):await api('POST','/rooms/join',{code:b.dataset.code});liveRoom=result.room;}
      else if(action==='leave-room'){await api('POST','/rooms/'+liveRoom.code+'/leave',{});liveRoom=null;}
      else if(action==='accept'||action==='decline')await api('POST','/friends/'+b.dataset.id,{accept:action==='accept'});
      else if(action==='title'){await api('PATCH','/me/preferences',{title:b.dataset.title});applyProfile((await api('GET','/me')).profile);}
      liveHub=await api('GET','/club');
    });return;
  }
  if(!backendReady)return;
  if(b.dataset.tab==='rooms'&&!b.closest('.nav')||b.dataset.action==='friends'){e.preventDefault();e.stopImmediatePropagation();navigate('club');return;}
  if(b.dataset.action==='profile'){e.preventDefault();e.stopImmediatePropagation();openAccount();return;}
  if(b.dataset.filter||b.dataset.action==='friends-filter'){e.preventDefault();e.stopImmediatePropagation();if(b.dataset.filter)leaderFilter=b.dataset.filter;else friendsOnly=!friendsOnly;refreshStandings();shell();return;}
  if(b.dataset.action==='claim'){e.preventDefault();e.stopImmediatePropagation();onlineTask(async()=>{applyProfile((await api('POST','/claim',{})).profile);toast('250 club points, on the house.');});return;}
  if(!round?.server)return;
  let type,extra={};
  if(b.dataset.action==='hit'||b.dataset.action==='stand'){type=b.dataset.action;}
  else if(b.dataset.action==='draw'){type='draw';extra.held=round.held??[];}
  else if(b.dataset.answer){type='answer';extra.answer=b.dataset.answer;}
  else if(b.dataset.memoryCell!==undefined){type='flip';extra.index=Number(b.dataset.memoryCell);}
  else if(b.dataset.slideTile!==undefined){type='slide';extra.tile=Number(b.dataset.slideTile);}
  else if(b.dataset.lightCell!==undefined){type='toggle';extra.index=Number(b.dataset.lightCell);}
  else if(b.dataset.connectColumn!==undefined||b.dataset.action==='connect-drop'){type='drop';extra.column=Number(b.dataset.connectColumn??$('#connect-column-select').value);}
  else if(b.dataset.action==='code-submit'){type='guess';extra.guess=[...round.extra.draft];}
  if(type){e.preventDefault();e.stopImmediatePropagation();serverAction(type,extra);}
},true);
document.addEventListener('keydown',e=>{if(!round?.server||currentGame().id!=='slide'||dialog.open||!e.target.closest?.('[data-slide-tile]'))return;const direction={ArrowUp:-3,ArrowDown:3,ArrowLeft:-1,ArrowRight:1}[e.key];if(!direction)return;e.preventDefault();e.stopImmediatePropagation();const blank=round.extra.tiles.indexOf(0),next=blank+direction;if(slideNeighbours(blank).includes(next))serverAction('slide',{tile:round.extra.tiles[next]});},true);
document.addEventListener('submit',e=>{const kind=e.target.dataset.onlineForm;if(!kind)return;e.preventDefault();e.stopImmediatePropagation();const form=new FormData(e.target),values=Object.fromEntries(form);onlineTask(async()=>{
  if(kind==='register'||kind==='login'){const result=await api('POST','/auth/'+kind,values);setSession(result.csrf);applyProfile(result.user);round=null;cancelAnimationFrame(spinFrame);clearTimeout(spinTimer);clearTimeout(memoryCloseTimer);if(result.round)applyPacket({round:result.round});liveHub=null;liveRoom=null;onlineHeld={};dialog.close();toast('Your account is connected.');}
  else if(kind==='create-room'){const result=await api('POST','/rooms',{...values,bestOf:Number(values.bestOf)});liveRoom=result.room;}
  else if(kind==='join-room')liveRoom=(await api('POST','/rooms/join',values)).room;
  else if(kind==='friend'){await api('POST','/friends',values);toast('Friend request sent.');}
  else if(kind==='invite'){await api('POST','/rooms/'+liveRoom.code+'/invite',values);toast('Room invite sent.');}
  liveHub=await api('GET','/club');
});},true);
setInterval(()=>{if(tab==='club'&&!document.hidden&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))refreshClub();},2500);
onlineBoot();

